return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Basque','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 17:45+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'eu','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Baliabide anitzeko bidegurutzeak, SEO meta etiketak, eta AI eduki tresnak WordPress-entzat. Hizkuntza detekzioa, URL bidegurutzeak, hreflang, meta deskribapenak, eta AI-k powered laburpen, meta, eta itzulpen ezaugarriak konbinatzen ditu.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Itzuli','Lingua Forge — Quick Translate'=>'Lingua Forge — Azkar Itzuli','Informative'=>'Informativo','Persuasive'=>'Beldurgarria','Storytelling'=>'Istorioak','Technical'=>'Teknikoa','Conversational'=>'Egunerokoa','Permission denied.'=>'Baimena ukatua.','Cannot determine target language from slug.'=>'Ezin da helburu hizkuntza slug-etik zehaztu.','Invalid post type.'=>'Post motaren errorea.','Invalid or primary language.'=>'Hizkuntza baliogabea edo lehenetsia.','Template not found or not stored in the database.'=>'Txantiloia ez da aurkitu edo ez da datu-basean gordeta.','Template has no content.'=>'Txantiloian ez dago edukirik.','No internal links found to update.'=>'Ez da barruko estekarik egon eguneratzeko.','%d link updated.'=>'%d esteka eguneratu da.' . "\0" . '%d esteka eguneratu da.','No language-specific template parts found to map.'=>'Ez da hizkuntza-espezifikoak diren txantiloia zatiak aurkitu mapatzeko.','No template part references needed updating.'=>'Ez da eguneratzeko behar diren txantiloia zatiaren erreferentziarik.','%d part reference updated.'=>'%d zatiko erreferentzia eguneratu da.' . "\0" . '%d zatiko erreferentzia eguneratu da.','Invalid language.'=>'Hizkuntza baliogabea.','Template part not found or not stored in the database.'=>'Ez da txantiloia zatiaren erroa edo ez da gordeta datu-basean.','Template part has no content.'=>'Ez dago edukirik txantiloia zatian.','No navigation references needed updating.'=>'Ez da nabigazio erreferentziarik egon eguneratzeko.','%d navigation reference updated.'=>'%d nabigazio erreferentzia eguneratu da.' . "\0" . '%d nabigazio erreferentzia eguneratu da.','No AI provider configured.'=>'AI hornitzaile konfiguratu gabe.','Missing pattern name or language.'=>'Patroiaren izena edo hizkuntza falta da.','Pattern not found.'=>'Ez da patroiarik aurkitu.','Pattern has no content to translate.'=>'Ez dago itzuli beharreko edukirik patroiak.','AI provider returned an empty response.'=>'AI hornitzaileak erantzun hutsa eman du.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Patroia itzuli eta gorde da. Edukia zure CPT postean kopiatzailearen bidez edo Erabilerako Blokearen sarreran erabili edo Erabilerako Blokearen hasierako puntutzat erabili.','Invalid template type.'=>'Txantiloia mota baliogabea.','Template "%s" already exists.'=>'"%s" jada existitzen da.','"%s" created.'=>'"%s" sortu da.','Invalid template part.'=>'Txantiloia zatia baliogabea.','Template part "%s" already exists.'=>'"%s" zatia jada existitzen da.','"%1$s" created. %2$d template updated.'=>'"%s" sortu da. %d txantiloia eguneratu da.' . "\0" . '"%s" sortu da. %d txantiloia eguneratu da.','Page'=>'Orria','Single'=>'Bakarra','Search'=>'Bilaketa','Search Results'=>'Bilaketa emaitzak','Archive'=>'Artxiboa','Front Page'=>'Lehentasuna Orria','Single: %s'=>'Bak: %s','Single %s'=>'Bak %s','Archive: %s'=>'Artxiboa: %s','%s Archive'=>'%s Artxiboa','No source content found to translate.'=>'Ez da itzultzeko iturri edukirik aurkitu.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Itzuli da. Ikuskaritza-sarean berrikusi — lotura barneak, nabigazio URL-ak eta txantiloiaren slug-ak ez dira automatikoki eguneratzen.','Navigation not found.'=>'Nabigaziorik ez da aurkitu.','Navigation has no content to translate.'=>'Nabigazioak ez du itzultzeko edukiarik.','"%1$s %2$s" saved.'=>'"%1$s %2$s" gorde da.','Translate page…'=>'Orria itzuli…','Generate content…'=>'Edukia sortu…','AI Behaviour Preset'=>'AI Portaera Aurrebista','Custom'=>'Pertsonalizatua','Global default (%s)'=>'Nazioarteko lehenetsia (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Aldatzen du AI lehenetsia Orriko Itzulpenean eta Edukiaren Sortzean. Gune osoan konfiguratutako prompt-eskakizunak (Ezarpenak → Portaera) beti gehitzen dira eskaera bakoitzean, aukeraketa honetatik independentea.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Aldatzen du AI lehenetsia Orriko Itzulpenean eta Edukiaren Sortzean. Beste ezaugarri guztiak beti erabiltzen dute lehenetsia globala.','Close'=>'Itxi','Translate missing'=>'Missing itzuli','From'=>'Nondik','Retranslate'=>'Itzuli berriro','Translating…'=>'Itzultzen…','Retranslating…'=>'Itzultzen berriro…','✓ Done'=>'✓ Eginda','Error'=>'Errorea','Navigation posts are translated via the Router tab, not this button.'=>'Nabigazio mezuak Router fitxan itzultzen dira, ez botoi honetan.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'"%s" post motarako itzulpenak sortzea aktibo dagoen integrazio bat behar du. Mesedez, ziurtatu integrazioa instalatuta eta aktiboa dagoela.','No %s version found in this translation group.'=>'Ez da %s bertsio bat aurkitu itzulpen talde honetan.','AI Usage'=>'AI Erabilera','Today'=>'Gaur','Last 7 days'=>'Azken 7 egun','Last 30 days'=>'Azken 30 egun','All time'=>'Denbora guztian','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Token kontsumoa ezaugarri, hornitzaile eta ereduen arabera. AI deien arruntean erregistratzen da; Test konexio pingak ez dira barne hartzen, totala oker ez dadin. Taula azkarra egunero biltzen du — aukeratu beheko leihoa ikusteko.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Oraindik ez da AI erabilerarik erregistratu. Behin editore batek itzulpena egin, meta deskribapena sortu edo beste AI ezaugarri bat erabili, totala hemen agertuko da.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Ez da AI erabilerarik erregistratu aukeratutako leihoan (%s). Aukeratu goiko zabalagoa.','Feature'=>'Ezaugarri','Provider'=>'Hornitzailea','Model'=>'Eredua','Requests'=>'Eskaerak','Input tokens'=>'Sarrerako tokenak','Output tokens'=>'Irteerako tokenak','Total tokens'=>'Token guztira','Total'=>'Guztira','API Keys'=>'API giltzak','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Giltzak AES-256-CBC enkriptatzen dira WordPress datu-basean gordetzeko. Enkriptazio sekretua zure WordPress autentifikazio gatz-iturrietatik dator (wp-config.php), beraz, testu hutseko giltzak ez dira inoiz datu-basean jartzen.','API Key'=>'API Giltza','Paste your API key…'=>'Itsatsi zure API giltza…','✓ Configured'=>'Konfiguratu da','✗ Not configured'=>'Ez da konfiguratu','Test connection'=>'Testatu konexioa','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Utzi hutsik eginez gakoa mantentzen da. Sartu balio berri bat ordezkatzeko.','Remove stored key'=>'Ezabatu gakoa gordeta','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Gakoa hau une honetan zerbitzariko %s batek hornitzen du eta ezin da hemen ezabatu. Sartu gakoa goian gainean eta datu-baseko balio batekin ordezkatu.','environment variable'=>'ingurune aldagaia','PHP constant'=>'PHP konstantea','Alternative (server-side):'=>'Alternatiba (zerbitzarian):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Gakoak ere definitu ditzakezu konstante edo ingurune aldagaitzat (adibidez, wp-config.php-n). Iturri horiek automatikoki erabiltzen dira datu-baseko gakoa ez dagoenean oinarrizko baliabide gisa.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Erabili nahi duzun enkriptazio sekretu pertsonalizatua (wp_salt balioa lortzeaz gain), gehitu hau wp-config.php-ra:','Unknown provider.'=>'Hornitzaile ezezaguna.','No API key configured for this provider.'=>'Ez dago API gako konfiguraturik hornitzaile honetan.','Could not instantiate the provider.'=>'Ezin izan da hornitzailea sortu.','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Hornitzaileak ez du testurik itzuli. Egiaztatu WordPress errore erregistroa huts eginaren arrazoi zehatza ikusteko.','Behavior'=>'Jokabidea','Block Editor'=>'Bloke Editorea','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge-k Gutenberg bi ezaugarri mugatzen du lehenetsian, hizkuntza arteko jokabidea koherente mantentzeko. Aukeratu hemen zuretzat beharrezkoa den Gutenberg / FSE gaitasun osoa izateko.','Block locking'=>'Blokearen blokeatzea','Allow editors to lock individual blocks'=>'Baimendu editoreek bloke bana blokeatzea','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Gutenberg-en canLockBlocks berriro aktibatzen du. Edizio txantiloietan erabilgarria da, kolaboratzaileek bloke zehatzak mugitu edo ezabatu ez ditzaten.','Template mode'=>'Txantiloi modua','Allow Gutenberg template-editing mode on post screens'=>'Baimendu Gutenberg-eko txantiloi editatzeko modua mezularitza pantailetan','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Re-enables supportsTemplateMode. Oinarrizko lan-fluxuak, non post mailako txantiloiak ukitzen diren, helburu da.','Compliance Preset'=>'Betetze aurrekoa','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Lege, araudi, mediku edo tekniko edukiaren gordetzeko modua. Aktibatzen denean, AI ezaugarri bakoitzak tenperatura baxu bat erabiltzen du eta behean gehitzen du sistema prompt-aren azpian — terminologia, artikulu zenbakiak, unitateak, marka izenak eta araudi hizkuntza bertan bertan gordetzen dira, ez paragrafatuak.','Global AI preset'=>'AI aurrekoa globala','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, ezaugarri bakoitzeko','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'AIren portaera lehenetsia ezartzen du webgune osoan. Post bakoitzak aldatu dezake Translatio eta Eduki Sortzailearen bidez Lingua Forge meta kutxa erabiliz.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standardak ezaugarri bakoitzaren tenperatura egokituaren erabilera du: Itzulpena T=0.2 ( zehatza), Azkar Itzulpena T=0.4, Eduki Sortzailea T=0.6 (kreatiboa). Beste aurrekoak tenperatura finkoa aplikatzen du ezaugarri guztietan.','Technical / Scientific instructions'=>'Tekniko / Zientziazko argibideak','Legal / Compliance instructions'=>'Lege / Betetze argibideak','Creative / Marketing instructions'=>'Kreatiboa / Marketin argibideak','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Utzi hutsik erabiltzeko ezarritako lehenetsia. Gorde aurretik ezarritako aldaketa ezabatzeak lehenetsia berreskuratuko du hurrengo gordetzean.','View built-in default'=>'Ikusi lehenetsia','Translation Memory'=>'Itzulpen Memoria','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Cache itzulpen baliokideak bloke mailan, eduki erabili daitekeenak (oina, alboak, akordeoiak, lege-oinarriak) API deia egin gabe. Aktibatuta, itzulpen fluxuak post bakoitza bloketan banatzen du, cache-an bilatzen du eta blokez kanpokoak AI-ra bidaltzen ditu eskaera batean. Glosario editaketak eta Betetze aurreko aldaketak automatikoki baliogabetzen dituzte cacheko itzulpenak. Estatistikak ikusi eta cachea garbitu Mantentzean.','Enable block-level translation cache reuse across posts'=>'Bloke mailako itzulpen cache erabili beste postetan','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Une honetan ez da erabiltzen, post-aren atributuaren placeholder-ak (wp:details laburpen eremuak, etab.) erabiltzen dituztenak — existitzen den itzulpen bide bakarrean pasatzen dira.','General'=>'Orokorra','Light'=>'Argia','Meta Description, Excerpt Generator'=>'Meta Deskribapena, Laburpen Sortzailea','Quality'=>'Kalitatea','Translation, Content Generator'=>'Itzulpena, Eduki Sortzailea','Active Provider'=>'Hornitzaile aktiboa','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Une honetan %s konstantea heredatzen da. Hemen balioa hautatzeak gaindituko du.','Models'=>'Modeloak','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Ezaugarriak bi mailatan banatzen dira. Sartu bakoitzaren identifikadore zehatza eta hornitzailearen izena. Utzi hutsik, lehenetsia erabiltzeko. Aktibo den hornitzailearen modeloak bakarrik deitzen dira exekuzioan — besteak aurretik konfiguratu behar dira aldatzeko.','active'=>'aktiboa','overridden'=>'gainditua','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tip: modelo bat lehenetsira berrezartzeko, garbitu eremua eta gorde.','Glossary'=>'Glosario','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Taula terminologikoaren kudeaketa erabiltzaileak hizketa bikoitzeko. Sarrera hauek gehitzen dira itzulpen sistemaren prompt-ean, AI-k termino hobesien erabilera jarraitzeko — dominen hizkuntzako lexikoan oso garrantzitsua ("kWp", "PPA", "interkonexio puntua"), markaren izenak ez dira itzuli behar, eta araudi estandarizatuen formulazioak. Bi hizketa eremuak aukera librekoa dira: utzi "Iturri hizkuntza" hutsik sartu nahi duzun hizkuntzaren araberakoa izan gabe; utzi "Helburu hizkuntza" hutsik, guztietara aplikatzeko.','Glossary entry added.'=>'Glossario sarrera gehitu da.','Glossary entry removed.'=>'Glossario sarrera ezabatu da.','Could not add entry: source term and target term are required.'=>'Ezin izan da sarrera gehitu: iturri terminoa eta helburu terminoa beharrezkoak dira.','Could not save the glossary entry.'=>'Ezin izan da glossario sarrera gorde.','Source language'=>'Hizkuntza iturriaren','— Any —'=>'— Edozein —','Target language'=>'Helburu hizkuntza','— Any target —'=>'— Edozein helburu —','Filter'=>'Filtroa','Reset'=>'Berrezarri','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Ez dago oraindik filtroarekin bat datorren glossario sarrerarik. Garbitu filtroa guztiz ikusteko edo sartu berri bat gehitzeko behean.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Oraindik ez dago glossario sarrera. Gehitu behean terminologia betetzeko itzulpenetan.','Source term'=>'Iturri terminoa','Target term'=>'Helburu terminoa','Source lang'=>'Iturri hizkuntza','Target lang'=>'Helburu hizkuntza','Notes'=>'Oharra','any'=>'edozein','Delete this glossary entry?'=>'Ezabatu glossario sarrera hau?','Delete'=>'Ezabatu','Add new entry'=>'Gehitu sarrera berria','The phrase as it appears in the source text.'=>'Iturri testuan agertzen den esamena.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Itzulpenan nola agertu behar duen. Iturri terminoa berdin gordetzeko AIri instrukzioa emateko, balio bera eman itzultzeko.','— Any source language —'=>'— Edozein iturri hizkuntza —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Utzi hutsik marken izenak eta hizkuntzarekiko ezberdintasunak ez diren terminoa betetzeko, itzultzen garenean.','— Any target language —'=>'— Edozein helburu hizkuntza —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Utzi hutsik, sarrera hau guztietara aplikatzeko — marka izenak, laburdurak eta beti berdin gordetzeko terminoa.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Aukerazko testuingurua editoreentzat (adibidez, "ASIC = Application-Specific Integrated Circuit; ingelesean gorde tekniko testuinguruetan").','Add entry'=>'Gehitu sarrera','Limits'=>'Muga','Authors and above (edit_published_posts)'=>'Egileak eta gehiago (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Garatzaileak eta gehiago — lehenetsia (edit_posts)','Editors and above (edit_others_posts)'=>'Editoreak eta gehiago (edit_others_posts)','Administrators only (manage_options)'=>'Administratzaileak bakarrik (manage_options)','AI Limits & Security'=>'AI Muga eta Segurtasuna','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Murriztu AI erabilera muga eta baimendu erabiltzaile rol batzuk AI bidezko deien kostuak kontrolatzeko. Erabiltzaile bakoitzeko tasa-muga gainditzen du (30 eskaera / minutua, kodean ezarrita), eta bakarrik erabiltzaile bakarraren abiadura kontrolatzen du.','Daily request limit'=>'Eguneko eskaera muga','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'AI eskaerak UTC egunean (biak Toolbar itzulpenak eta blokeko berrikuspenak) muga. Kontagailua UTC erdian berritzen da. Utzi 0, muga desgaitu nahi baduzu.','Minimum role'=>'Gutxieneko rola','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'AI ezaugarriak aktibatzeko aukera ematen duen WordPress gaitasun minimoa. Honek multi-autor guneetan murrizten du, Kontribuzioak edo proba kontuak AI bidezko deien kostuak saihesteko. Gainbegiratu ezazu funtzioen arabera linguaforge_required_capability filter bidez.','Translation Limits'=>'Itzulpen Muga','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Nola kontrolatu edukiaren kantitatea AIra bidaltzen dena eta erantzunaren tamaina. Utzi hutsik, balio lehenetsia erabiltzeko. Handitu balioak orri handiak moztu badira; jaitsi API kostuak murrizteko.','Model tier'=>'Modelo maila','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Kalitatea (lehentasuna — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Argia (azkar eta kostu eraginkorra — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Zein modelo maila erabili itzulpen osoarentzat. Kalitatea goian ezarritako Modelo taulan konfiguratutako modeloa erabiltzen du eta gomendatzen da zehaztasun handiko, luzeak diren itzulpenetan. Aldatu Argira, azkartasuna edo kostua lehentasuna bada eta edukia laburra bada.','Max output tokens'=>'Max tokens output','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Max tokens kopurua AIk ekoiztu dezakeen itzulpen erantzun batean. Itzulpen bat isilpean moztu bada, handitu balio hau. Lehenetsia: 16.000.','Max input characters'=>'Max karaktere input','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Postaren edukia bidali zaion karakter kopururik handiena. 0 ez du mugarik — beti bidaltzen da edukia osoa (gomendatua). Ezarri balio ez-zeroa zure hornitzaileak testuinguru leiho estu bat duenean. Abisua PHP errore erregistroan idazten da edukia moztu denean.','Quick Translation'=>'Azkar Itzulpena','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Azkar Itzulpena erabilia da zatitxo/modu laburretan — pasarte laburrek eskaeraz itzultzen dira tresnabarra, editorea edo blokea popoverak erabiliz. Konfigurazio arinagoa erabiltzen du, orri osoaren itzulpenetik, erantzunak azkarrago eta kostu txikiagoa izan dadin.','Light (default — fast and cost-effective)'=>'Arina (lehena — azkar eta kostu txikia)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Kalitatea (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Arin mailak model azkarrena erabiltzen du goiko Modeloak taulan konfiguratutako moduan (lehena: Haiku / Flash). Aldatu Kalitatera, zatitxoetan orri osoaren itzulpenaren zehaztasuna behar duzunean.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'AI-k ekoiztu dezakeen token kopururik handiena itzulpen azkar bakoitzeko. Lehenetsia: 2.000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Sarrerako eremuak onartzen dituen karakter kopururik handiena. Lehenetsia: 8.000.','Content Generator'=>'Eduki Sortzailea','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'AI Eduki Sortzailearen token aurrekontua eta sarrera mugak kontrolatzen ditu. Utzi eremuak hutsik, ezarritako balioekin erabiltzeko.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'AI-k ekoiztu dezakeen token kopururik handiena sortze bakoitzeko. Handitu hori, artikulu osoak moztu gabe geratzen direnean. Lehenetsia: 8.192.','Max hints characters'=>'Gomendioen karaktere maximoa','Maximum characters read from the Hints field. Default: 2 000.'=>'Gomendioen eremutik irakurritako karaktere maximoa. Lehenetsia: 2.000.','Max context characters'=>'Testuinguru maximoa','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'AIri pasatzen zaion edukia, gomendiorik ez dagoenean, hazi testuinguru gisa. Lehenetsia: 6.000.','Maintenance'=>'Mantentze-lanak','Language Overrides'=>'Hizkuntza Aldaketak','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Gorde konpilatutako .mo fitxategiak hirugarren aldeko pluginen testuak ordezkatzeko, esaterako, VikBooking itzulpen pertsonalizatua "etxea" ordez "gela" erabiltzen duena. Fitxategiak WordPress izenburuaren arauak jarraitu behar ditu: {textdomain}-{locale}.mo (adibidez, vikbooking-ca.mo). Uploads karpetan gordetzen dira eta plugin eguneraketekin iraun dezakete.','Override file uploaded successfully.'=>'Orriaren ordezkoa arrakastaz kargatu da.','Override file deleted.'=>'Ordezkatzeko fitxategia ezabatu da.','No file was selected.'=>'Ez da fitxategirik aukeratu.','Only .mo files are accepted.'=>'Only .mo fitxategiak onartzen dira.','The upload failed — please try again.'=>'Kargatzea huts egin du — saiatu berriro.','Could not save the file. Check that the uploads folder is writable.'=>'Ez da fitxategia gorde. Egiaztatu upload karpeta idazgarria dela.','Invalid filename.'=>'Fitxategi izenburu baliogabea.','Security check failed — file path is not permitted.'=>'Segurtasun kontrola huts egin du — fitxategiaren bidea ez da baimendua.','An unknown error occurred.'=>'Errore ezezaguna gertatu da.','Text domain / locale'=>'Testu domeinua / hizkuntza','Files'=>'Fitxategiak','Size'=>'Tamaina','Delete all files for this override (both .mo and .po)?'=>'Ezabatu fitxategi guztiak ordezkaritza honetan (biak .mo eta .po)?','No override files uploaded yet.'=>'Oraindik ez da ordezkaritza fitxategirik kargatu.','Upload .mo file'=>'Kargatu .mo fitxategia','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Only konpilatutako .mo fitxategiak onartzen dira. Fitxategiak {textdomain}-{locale}.mo eredua jarraitu behar du. Fitxategi batek izen bera badu beste batekin, ordeztuko du.','Upload Override'=>'Kargatu Ordezkaketa','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Kopiatu Segurtasun Gunean','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate bere itzulpen pertsonalak wp-content/languages/loco/ kokatzen ditu — leku hori WP eguneraketak, plugina berrabiarazteak edo Loco Translate ezabatzeak ezabatzen du. Fitxategiak hemen kopiatzeak Lingua Forge i18n-overrides direktorioan jartzen ditu, eta horrek iraun duzuen bitartean mantentzen da, eta automatikoki kargatzen da eskaera bakoitzean.','File copied to safe storage successfully.'=>'Fitxategia arrakastaz kopiatuta segurtasun gunean.','Source file not found.'=>'Iturri fitxategia ez da aurkitu.','Could not copy the file. Check that the uploads folder is writable.'=>'Ez da fitxategia kopiatzen. Egiaztatu upload karpeta idazgarria dela.','Invalid file reference.'=>'Fitxategi erreferentzia baliogabea.','Type'=>'Mota','✓ In safe storage'=>'✓ Segurtasun gunean','Copy to safe storage'=>'Kopiatu segurtasun gunean','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Oraindik ez da Loco Translate fitxategirik aurkitu. Itzulpena gordetzen duzunean agertzen da hemen.','AI Cache'=>'AI Cache','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'Lingua Forge-k AI-k sortutako itzulpenak, meta deskribapenak, pasarteak eta eduki sortuak cache-etan gordetzen ditu, sarrera aldaketek API ordainpeko deia berriro ez eragiteko. Cache-ak automatikoki ezabatzen dira sarrera aldaketak gertatzen direnean. Garbitu cachea eskuz, datu-baseko espazioa berreskuratzeko, hornitzailea aldatzean edo prompt txantiloiak editatzean, edo cache-arekin arazo bat izanez gero.','AI cache cleared. %d entry was removed.'=>'AI cachea garbitu da. %d sarrera ezabatu da.' . "\0" . 'AI cachea garbitu da. %d sarrera ezabatu dira.','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Garbitu AI cacheko emaitza guztiak? Etorkizuneko eskaerak API deia berriro eragingo du cachea berritzen den arte.','Clear AI Cache'=>'Garbitu AI Cache','Debug Files'=>'Debug Fitxategiak','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Debug log-ak aktibatuta dagoenean (beheko toggle bidez edo wp-config.php-n LINGUAFORGE_AI_DEBUG definituz), Itzulpen eta FSE txantiloi itzulpen ezaugarriak AI prompt eta erantzunak diskoan idazten dituzte arazteak egiteko. Erabili atal hau irteera hori monitorizatzeko eta garbitu behar duzunean — fitxategiak azkar handitzen dira orri handietan. Konfiguratu helbide direktorioa linguaforge_debug_dir iragazkiaren bidez.','Debug files cleared. %d file was removed.'=>'Debug fitxategiak garbitu dira. %d fitxategi bat kendu da.' . "\0" . 'Debug fitxategiak garbitu dira. %d fitxategi kendu dira.','Debug logging enabled.'=>'Debug log-ak aktibatuta daude.','Debug logging disabled.'=>'Debug log-ak desaktibatuta daude.','Debug logging'=>'Debug log-ak','Write AI prompts and responses to disk for troubleshooting'=>'AI prompt eta erantzunak diskoan idaztea arazteak egiteko','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Linguaforge_AI_DEBUG konstanteak wp-config.php-n behartu du. Lerro hori ezabatu toggle hau kontrolatzeko hemen.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Linguaforge_AI_DEBUG konstanteak wp-config.php-n behartu du. Lerro hori ezabatu toggle hau kontrolatzeko hemen.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Fitxategiak beheko direktorian kokatzen dira. Itzulpen arazoak diagnostikatzeko erabilgarria — itzali behar duzu behar duzuna lortu arte, bestela fitxategiak handitzen dira. Hau behartu dezakezu wp-config.php-tik `define( \'LINGUAFORGE_AI_DEBUG\', true );` erabiliz, toggle hori gainetik.','Currently:'=>'Unean','✓ Enabled'=>'✓ Aktibatuta','✗ Disabled'=>'✗ Desaktibatuta','Directory'=>'Direktorioa','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtratu linguaforge_debug_dir erabiliz, debug irteera ezkutuko kokapen batera bideratzeko.','.txt file(s) in the directory'=>'Direktorioan .txt fitxategi(a)','Save Debug Setting'=>'Gorde Debug Konfigurazioa','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Ezabatu debug direktorioan dauden .txt fitxategi guztiak? Direktorioa bera geratuko da, etorkizuneko debug idatziak garbi iritsi daitezen.','Clear Debug Files'=>'Garbitu Debug Fitxategiak','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'Bloke bakoitzeko itzulpen cachea partekatzen da posten artean. Konfiguratu piztu/itzali Ezarpenetan → Portaera. Beheko estatistikek erakusten dute zer cacheatzen den une honetan; garbitzeak bloke bakoitza berriro itzultzea behartzen du hurrengo eskaeran (baliozkoa modeloak eguneratu ondoren edo datu-baseko espazioa berreskuratzeko).','Translation Memory cleared. %d cached block was removed.'=>'Itzulpen Memoria garbitu da. %d cacheatutako blokea kendu da.' . "\0" . 'Itzulpen Memoria garbitu da. %d cacheatutako bloke kendu dira.','Status'=>'Egoera','— toggle in Settings → Behavior.'=>'— toggle Ezarpenetan → Portaeran.','Cached blocks'=>'Cacheatutako blokeak','Cumulative cache hits'=>'Bilketa cacheko iristeak','(avg %.1f hits/block)'=>'(batez besteko %.1f iriste/blokea)','Oldest entry'=>'Goreneko sarrera','Newest entry'=>'Azkeneko sarrera','Approximate size'=>'Tamaina hurbila','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Garbitu Itzulpen Memoria osoa? Etorkizuneko itzulpenek cachea berriro eraikiko dute.','Clear Translation Memory'=>'Garbitu Itzulpen Memoria','Uninstall Behaviour'=>'Desinstalazio Portaera','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Kudeatzen du zer gertatzen den administratzaileak plugin-a ezabatzen duenean Plugins → Installed Plugins → Delete. Pluginaren ezarpenak eta AI cache-ak beti ezabatzen dira. Hizkuntza esleipenak eta itzulpen harremanak mantentzen dira lehenetsita, beraz, desinstalazio edo berrinstalazio batetik bertara itzuli daiteke.','Uninstall setting saved.'=>'Desinstalazio ezarpena gorde da.','Delete content data on uninstall'=>'Ezabatu edukien datuak desinstalazioan','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Era berean, ezabatu hizkuntza esleipenak, itzulpen harremanak, meta deskribapenak, glosarioa eta Itzulpen Memoria plugin-a desinstalatzen denean.','Warning:'=>'Abisua:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Egiaztatzen baduzu, plugin-a desinstalatzen duzunean, hizkuntza esleipen guztiak, itzulpen harremanak, meta deskribapenak, orrialdeko aurresetak, AI glosarioa eta Itzulpen Memoria betirako ezabatuko dira gune honetan. Hau ezin da desegin. Ez egiaztatu, gunean aniztasun hizkuntzak guztiz ezabatu nahi baduzu.','Save Uninstall Setting'=>'Gorde Desinstalazio Ezarpena','Router'=>'Router','Primary language saved.'=>'Hizkuntza nagusia gorde da.','Permalink rules flushed successfully.'=>'Permalinka arauak arrakastaz bideratu dira.','Primary Language'=>'Hizkuntza Nagusia','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Hizkuntza nagusia beti zerbitzatzen da zure gunearen erroan — ez URL aurrizkia bide moduan, ez hizkuntza azpian domeinua moduan. Beste hizkuntzak edo /lang/ bide aurrizkia (adibidez example.com/de/) edo hizkuntza azpian domeinua (de.example.com) erabiltzen dituzte, beheko URL egitura ezarpenaren arabera.','Primary language'=>'Hizkuntza nagusia','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Hizkuntza nagusia aldatu ondoren, permalinka guztiak bota (beheko atala) URL bideraketa eguneratzeko.','URL structure'=>'URL egitura','Path prefix — example.com/de/'=>'Bide-izena — example.com/de/','Subdomain — de.example.com/'=>'Azpi-domein — de.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Azpi-domein moduak zure web zerbitzariari eskatzen dio azpi-domein hizkuntzak (adibidez, de.example.com) WordPress instalazio honetara zuzentzea. Moduak aldatzean, permalinka arauak bota eta cache-ak garbitu. Zure hasierako URL-an www badago (adibidez, www.example.com), lf_base_domain iragazkia erabili domeinaren goiko maila ezkutatzeko, azpi-domeinak era egokian eraikitzeko.','Browser language redirect'=>'Nabigatzailearen hizkuntzaren birzirkulazioa','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Bisitzaileak birzirkulatu bere nabigatzailearen Accept-Language goiburua oinarrituta','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Gaituta, lehenengo aldiz bisitatzaileek hizkuntza cookiea edo URL-an hizkuntza aurrebista ez badute, hurbilen dagoen hizkuntza bertsiora birzirkulatuko dira. Birzirkulazioa saihesten da nabigatzailearen hizkuntza aktiboen artean ez badago. Bisitari batek hizkuntza bat hautatzen duenean, cookieak lehentasuna hartzen du eta nabigatzailearen goiburua ez da kontuan hartzen bisita guztietan.','Save Router Settings'=>'Gorde Router-ezintzak','Flush Permalinks'=>'Bota Permalinks','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'WordPressen berridazketa arauak berriro sortzen ditu URL-aren aurkezpenak, hizkuntza-espezifikoak eta artxibo berridazketak bat etortzeko. Oinarrizko hizkuntza aldatzean edo hizkuntza berriak gehitzean beharrezkoa.','Flush Permalink Rules'=>'Bota Permalink Arauak','Active Languages'=>'Hizkuntzak aktiboak','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Router-ek ezagutzen dituen hizkuntzak (WordPressen locale paketeak eta oinarrizko hizkuntza). Instalatu hizkuntza pakete gehiago beheko atalean, bidegurutze eta itzulpenetarako gehiago hizkuntza erabilgarri egiteko.','%d locale pack installed.'=>'%d locale pack instalatuta.' . "\0" . '%d locale pack instalatuta.','Install a Language'=>'Hizkuntza bat instalatu','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Deskargatu eta instalatu WordPressen hizkuntza pakete nagusia WordPress.org-etik. Instalatu ondoren, locale-a URL bidegurutze eta AI itzulpen lanerako erabilgarri izango da. Eskuragarri dauden hizkuntzen zerrenda eskakizunaren arabera lortzen da — sakatu beheko botoia kargatzeko.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Hizkuntza instalazioa desgaituta dago zerbitzarian. DISALLOW_FILE_MODS konstantea wp-config.php-n ezarrita dago. Instalatu hizkuntza paketeak eskuz WP-CLI bidez: wp language core install de_DE','Load available languages'=>'Kargatu hizkuntza erabilgarriak','— select a language —'=>'— hautatu hizkuntza —','Install'=>'Instalatu','Language Setup'=>'Hizkuntza konfigurazioa','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Ez dago bigarren hizkuntzarik konfiguraturik. Instalatu hizkuntza paketea goian, txantiloiak sortzeko aukera emateko.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Hautatu hizkuntza, bere FSE txantiloiak, zatiak eta nabigazio menuak kudeatzeko.','Forbidden'=>'Aurreikusi gabe','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Hizkuntza instalazioa desgaituta dago zerbitzarian (DISALLOW_FILE_MODS ezarrita dago).','Invalid locale code.'=>'Hizkuntza kode baliogabea.','Language %s installed successfully.'=>'Hizkuntza %s arrakastaz instalatu da.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Hizkuntza paketea instalatzea huts egin du. Hizkuntza jada instalatuta egon daiteke, locale kodea okerra izan daiteke, edo zure zerbitzariak fitxategien idazketa bloke dezake.','Navigations'=>'Nabigazioak','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Nabigazioaren itzulpena AI hornitzaile aktibo baten beharra du. Konfiguratu API giltza API Giltzen fitxan.','Navigation'=>'Nabigazioa','Action'=>'Ekintza','Re-translate'=>'Berriz itzuli','CPT Block Patterns'=>'CPT Bloke Patternak','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Ezarritako blokeak post moten pertsonalizatuak. Erabili Itzuli botoia hizkuntza bertsioa sortzeko. Edukia itzulita hemen gordetzen da eta CPT post batean kopiatu daiteke blokea editorearen Pattern inserter-etik edo erabil daiteke Pattern Sinked (Erabilgarri Blokea) hasteko.','Pattern'=>'Patron','Post Types'=>'Post Motak','✓ Translation saved'=>'✓ Itzulpena gorde da','View'=>'Ikusi','Template Parts'=>'Txantiloien Zatiak','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Gaia-oinarritutako kopiak, hizkuntzaren arabera. Eskemak sortu ondoren, txantiloiak hizkuntzaren arabera eguneratzen dira.','Part'=>'Zatia','Status / Actions'=>'Egoera / Ekintza','Fix Links'=>'Aldatu Estekak','Fix Nav'=>'Aldatu Nabigazioa','Create'=>'Sortu','Templates'=>'Txantiloiak','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Aktiboen gaian oinarritutako FSE txantiloiak. Sortu eta pertsonalizatu Webgune Editorean.','Actions'=>'Ekintzak','Fix Parts'=>'Aldatu Zatiak','Create missing'=>'Sortu gabeak','Translate all'=>'Itzuli guztiak','Fix all parts'=>'Konpondu atal guztiak','Fix all links'=>'Konpondu estekak guztiak','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','Testing…'=>'Testing…','✓ Connection OK'=>'✓ Konexioa ondo','✗ Failed:'=>'✗ Huts egin du: ','No response from provider — check the error log for details.'=>'Hornitzailearen erantzunik ez — egiaztatu errore erregistroa xehetasunak egiteko.','Network error — could not reach the WordPress AJAX endpoint.'=>'Sareko errorea — ezin izan da WordPress AJAX puntura iritsi.','Loading…'=>'Kargatzen…','Installing…'=>'Instalatzen…','✓ Language installed.'=>'✓ Hizkuntza instalatu da.','✗ Error:'=>'✗ Akatsa:','Creating…'=>'Sortzen…','✓ All templates created.'=>'✓ Txantiloi guztiak sortu dira.','Some templates could not be created.'=>'Etxe batzuk ezin izan dira sortu.','✓ All parts created.'=>'✓ Atal guztiak sortu dira.','Some parts could not be created.'=>'Etxe batzuk ezin izan dira sortu.','✓ All translated.'=>'✓ Itzulpen guztiak egin dira.','Some translations failed.'=>'Itzulpen batzuk huts egin dute.','Review carefully — links and slugs not updated.'=>'Aztertu arretaz — estekak eta slugak ez dira eguneratu.','Fixing…'=>'Konpontzen…','✓ Links fixed.'=>'✓ Estekak konponduta.','Some link fixes failed.'=>'Etxe batzuk konponketak huts egin dute.','✓ Parts fixed.'=>'✓ Atalak konponduta.','Some part fixes failed.'=>'Atal batzuk konponketak huts egin dute.','✓ Nav refs fixed.'=>'✓ Nabigazio erreferentziak konponduta.','Some nav ref fixes failed.'=>'Nabigazio erreferentziak konponketak huts egin dute.','✓ Pattern translated.'=>'✓ Patroi itzulita.','Pattern translation failed.'=>'Patroiaren itzulpena huts egin du.','Hide'=>'Ezkutatu','Built-in preset instructions:'=>'Prestatutako ezarpenak: ','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Ez da prestatutako ezarpenik — AI ezaugarriek beren ezarpenak erabiltzen dituzte. Bete beheko Pertsonalizatutako aginduen eremua zure webguneko arau propioak gehitzeko.','Settings'=>'Ezarpenak','You do not have permission to manage these settings.'=>'Ez duzu baimenik ezarpen hauek kudeatzeko.','Lingua Forge — Settings'=>'Lingua Forge — Ezarpenak','Settings saved.'=>'Ezarpenak gorde dira.','Save Settings'=>'Gorde Ezarpenak','Standard'=>'Estándarra','Technical / Scientific'=>'Teknikoa / Zientzia','Legal / Compliance'=>'Juridikoa / Betetze','Creative / Marketing'=>'Sortzailea / Marketina','Full Article'=>'Artikulu osoa','Introduction only'=>'Sarrera soil','Structured Outline'=>'Eskema antolatu','Generate Content'=>'Sortu Edukia','Hints'=>'Gomendioak','Key points, ideas, or structure to build from…'=>'Puntu nagusiak, ideiak edo eraikitzeko egitura...','Tone'=>'Tona','Output'=>'Irteera','Generate Excerpt'=>'Sortu Aipamena','Generate Meta Description'=>'Sortu Meta Deskribapena','Translate Content'=>'Itzuli Edukia','Mode'=>'Modua','Full post'=>'Post osoa','Translate chunk'=>'Itzuli zatia','Target Language'=>'Hizkuntza Helburu','Text to translate'=>'Itzuli beharreko testua','Paste a footnote, sentence, or any snippet here…'=>'Itsatsi ohar, esaldi edo zati hau...','Also generate meta description'=>'Era berean, sortu meta deskribapena','Translated Names'=>'Izendapenak itzuli','Name displayed in this language. Leave empty to use the source name.'=>'Izena hizkuntza honetan erakutsia. Utzi hutsik itzultzaile izena erabiltzeko.','Too many AI requests. Please retry in %d seconds.'=>'AI eskaera gehiegi. Saiatu berriro %d segundo barru.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'AI egutegiko kuota bete da (%1$d eskaera). Resetatzen da %2$s UTC-tan.','View Lingua Forge details'=>'Ikusi Lingua Forge xehetasunak','View details'=>'Ikusi xehetasunak','Visit plugin site'=>'Bisita ezarpenen webgunea','%d language not yet linked'=>'%d hizkuntza oraindik lotu gabe' . "\0" . '%d hizkuntza oraindik lotu gabe','This is the source page. Footnotes are edited directly in the block editor.'=>'Hau da iturri orria. Ohar-oinak zuzenean editatzen dira blokea editorean.','No source page linked yet.'=>'Oraindik ez dago iturri orririk lotuta.','The source page has no footnotes.'=>'Iturri orriaren ohar-oinik ez dago.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Ohar-oin hauek iturri orritik datoz eta hemen agertzen dira erreferentzia gisa soilik. Gehitu hauek orri honetan blokea editorea erabiliz.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d lokalizatutako txantiloi(ak) &#8220;%2$s&#8221; gaiarekin datu-basean gordeak daude, baina une honetan ez daude aktibo. Aktibatu berriro gaia berreskuratuz gero, aktibo egongo dira. Zure itzulpenak gaia berri horretara eramateko, berriro sortu <strong>Ezarpenak → Lingua Forge → Router → FSE eskema</strong> bidez.','Scanning posts for broken language links…'=>'Hitz egiten ari diren postak hizkuntza loturak hausten saiatzen…','Re-scanning…'=>'Berrikuspen…','Scan failed: '=>'Eskaneaketa huts egin du: ','unknown error'=>'Errorea ezezaguna','Scan request failed. Please try again.'=>'Eskaneatzeko eskaera huts egin du. Saiatu berriro.','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ {lang} ez da aurkitu. Ziurtatu itzuli diren post guztiek hizkuntza metadatuan {lang} ezarrita dutela.','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Ez da hautsi edo txantiloiak ez datoz bat aurkitu. Ikusi <strong>{scanned}</strong> post eta orri — guztiak ondo daude. Txantiloi zatien loturak (goiburua, oinarria, alboko barra) ez dira hemen sartzen — erabili Fix Template Parts botoia horiek banan banan egiaztatzeko.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> auto-konpondu daitezkeen lotura','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> eskuz berrikusi behar diren lotura','and'=>'eta','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Aurkitutako {parts} {total} postetan eta {scanned} aztertu direnetan {lang} hizkuntzarako.','Post'=>'Posta','Links'=>'Loturak','link(s)'=>'lotura(ak)','Fix'=>'Konpondu','✅ Fixed ({n})'=>'✅ Konponduta ({n})','⚠ No changes — re-scan?'=>'⚠ Ez da aldaketarik — berriro eskaneatu?','⚠ No changes'=>'⚠ Ez da aldaketarik','❌ Failed'=>'❌ Huts egin du','Done — {done} of {total} post(s) fixed.'=>'Eginda — {done} post eta orri {total} konponduta.','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} ez zuen ordezkagarri dauden loturarik — berriro eskaneatu ikusteko)}','Fixing {n} / {total}…'=>'{n} / {total} konpontzen…','URL could not be mapped to a post — check the link target exists'=>'URL ez da mapatu post batera — egiaztatu helburu lotura existitzen dela','No {lang} translation registered (TRID missing)'=>'Ez dago {lang} itzulpenik erregistratuta (TRID falta)','Translation found but permalink could not be generated'=>'Aurkitu da translatzea baina permalink-a ezin izan da sortu','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> bide zahar(ra)','📍 Stale path (page moved)'=>'📍 Bide zahar (orria mugituta)','{n} stale path(s)'=>'{n} bide zahar(ra)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> txantiloi arazo(ak)','📄 Wrong template'=>'📄 Txantiloi okerra','Expected: {expected}'=>'Itxaron: {expected}','Current: {current}'=>'Unekoa: {current}','Template "{expected}" does not exist — create it in the Site Editor first.'=>'"{expected}" izeneko txantiloi ez da existitzen — sortu lehenengo Gune Editorean.','Fix Template'=>'Konpondu Txantiloa','✅ Template fixed'=>'✅ Txantiloa konponduta','Internal Link Fixer'=>'Barneko Lotura Konpontzailea','Fix All'=>'Konpondu Guztiak','Re-scan'=>'Birbideratu','Language Switcher'=>'Hizkuntza Aldatzen','Displays the Lingua Forge language switcher.'=>'Lingua Forge hizkuntza aldatzailearen pantaila erakusten du.','Language'=>'Hizkuntza','Display'=>'Erakutsi','Language label'=>'Hizkuntza etiketa','Icon only'=>'Ikono bakarra','Icon + label'=>'Ikono + etiketa','Dropdown direction'=>'Dropdown norabidea','Down'=>'Behera','Up'=>'Gora','You do not have permission to read this post.'=>'Ez duzu baimenik irakurtzeko posta hau.','Post not found.'=>'Posta ez da aurkitu.','Limit results to pages in the given Lingua Forge language code.'=>'Mugatu emaitzak Lingua Forge hizkuntza kodean dauden orrietan.','Meta Description'=>'Meta Deskribapena','Using custom meta description.'=>'Metadatu pertsonalizatu bat erabiltzen','Prefilled from excerpt. Edit to override.'=>'Aldizkariaren zatitik aurretik bete. Aldatu nahi baduzu, editatu.','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Helburu 120–160 karakteretan. Utzi hutsik zatia erabili nahi baduzu.','↺ Refreshing…'=>'↺ Freskatu…','Review translation before applying'=>'Aztertu itzulpena aplikatu baino lehen','Current title'=>'Uneko izenburua','Translated title'=>'Itzulitako izenburua','Current content (will be overwritten)'=>'Uneko edukia (gaur egun ordezkatuko da)','Translated content'=>'Itzulitako edukia','Footnotes payload (advanced)'=>'Ohar zinta ( aurreratua)','Generated meta description'=>'Sortutako meta deskribapena','Saved to the meta description field when you apply.'=>'Gorde meta deskribapen eremuan aplikatzen duzunean.','Cancel'=>'Ezeztatu','Apply translation'=>'Aplikatu itzulpena','Generated Content'=>'Sortutako Edukia','Refine further:'=>'Hobetu gehiago:','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Gehitu jarraibideak zirriborroa hobetu - adibidez, laburtu, laburpen atala gehitu, erabili erregistro formalagoa, FAQ blokea gehitu…',